function validate([students]) {
  if (students.length > 100) return 'students holds at most 100 records.';
  for (const record of students) {
    if (record.length !== 2) return 'Each record is a pair [studentId, benchId].';
    if (record[0] < 1 || record[0] > 100) return 'Each studentId is between 1 and 100.';
    if (record[1] < 1 || record[1] > 100) return 'Each benchId is between 1 and 100.';
  }
  return null;
}

