function maxStudentsOnBench(students) {
  const benches = new Map();
  let best = 0;
  for (const [studentId, benchId] of students) {
    if (!benches.has(benchId)) {
      benches.set(benchId, new Set());
    }
    const seated = benches.get(benchId);
    seated.add(studentId);
    best = Math.max(best, seated.size);
  }
  return best;
}

