function maxStudentsOnBench(students) {
  // For each record's bench, list the student ids on that bench, sort them and count the distinct values.
  let best = 0;
  for (const [, bench] of students) {
    const ids = students.filter(record => record[1] === bench).map(record => record[0]).sort((a, b) => a - b);
    let distinct = 0;
    for (let i = 0; i < ids.length; i++) if (i === 0 || ids[i] !== ids[i - 1]) distinct++;
    if (distinct > best) best = distinct;
  }
  return best;
}

