function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? 100 : pick(0, 10);
  // A few benches and a few students make repeated pairs and shared benches common.
  const benchIds = Array.from({ length: large ? pick(1, 12) : pick(1, 4) }, () => pick(1, 100));
  const studentIds = Array.from({ length: large ? pick(10, 100) : pick(1, 6) }, () => pick(1, 100));
  const students = [];
  for (let i = 0; i < n; i++) {
    students.push([studentIds[pick(0, studentIds.length - 1)], benchIds[pick(0, benchIds.length - 1)]]);
  }
  return [students];
}
